using NUnit.Framework;
using WFC.Core;


// Generated by Claude
namespace WFC.Tests {
    /// <summary>
    /// A flat terrain set is a hierarchy with a root and one leaf per terrain, so it must keep producing the layouts
    /// of the original flat solver. The expected hashes were recorded from that solver.
    /// </summary>
    public class WFCFlatRegressionTests {
        const int Width = 12, Height = 10;

        static readonly ulong[][] Expected = {
            // windows off, shared weights
            new[] { 12996837703470516800UL, 7167695197208888263UL, 635042352517813708UL, 1896935707272942767UL },
            // windows off, per-cell weights
            new[] { 4828083697690194112UL, 11774303304822481194UL, 13607187972374021405UL, 1556956196360912631UL },
            // windows on, shared weights
            new[] { 11708714145926873761UL, 7397104918000489280UL, 1313624998543278504UL, 14464684208015799148UL },
            // windows on, per-cell weights
            new[] { 4828083697690194112UL, 11774303304822481194UL, 175248120482450050UL, 1556956196360912631UL }
        };

        static WFCRules ChainRules(bool windows) {
            var b = new WFCRulesBuilder(4) { diagonalRules = true };
            b.AllowCardinal(0, 1).AllowCardinal(1, 2).AllowCardinal(2, 3);
            b.AllowDiagonal(0, 1).AllowDiagonal(1, 2).AllowDiagonal(2, 3);
            b.SetWeight(0, 1f).SetWeight(1, 2f).SetWeight(2, 1f).SetWeight(3, 0.5f);
            if (windows) {
                // Terrain 1 may not become a one-cell strip between two terrain-2 cells.
                bool[] renderable = new bool[256];
                for (int m = 0; m < 256; m++) {
                    bool n = (m & 1) != 0, s = (m & 16) != 0, e = (m & 4) != 0, w = (m & 64) != 0;
                    renderable[m] = !(n && s && !e && !w);
                }

                b.AddWindow(2, 1UL << 1, renderable);
            }

            return b.Build();
        }

        static ulong Hash(int[] values) {
            ulong hash = 1469598103934665603UL;
            foreach (int value in values) {
                hash ^= (ulong)(uint)value;
                hash *= 1099511628211UL;
            }

            return hash;
        }

        static float[] CellWeights(ulong seed) {
            float[] weights = new float[Width * Height * 4];
            var     rng     = new SplitMix64(seed * 7919);
            for (int i = 0; i < weights.Length; i++) weights[i] = 0.05f + rng.NextFloat();
            return weights;
        }

        [Test]
        public void FlatHierarchyReproducesTheOriginalSolver() {
            int row = 0;
            foreach (bool windows in new[] { false, true }) {
                foreach (bool perCell in new[] { false, true }) {
                    using var implicitFlat = new WFCSolver(ChainRules(windows), Width, Height, perCell);
                    using var explicitFlat = new WFCSolver(ChainRules(windows), Width, Height, perCell,
                        semanticGraph: SemanticGraphCompiler.Flat(4));

                    for (int i = 0; i < 4; i++) {
                        ulong seed = (ulong)(i + 1);
                        float[] weights = perCell ? CellWeights(seed) : null;

                        Assert.AreEqual(WFCStatus.Success, implicitFlat.Solve(seed, default, weights, 100, windows));
                        Assert.AreEqual(1, implicitFlat.LastAttempts);
                        Assert.AreEqual(Expected[row][i], Hash(implicitFlat.Layout), $"windows={windows} perCell={perCell} seed={seed}");

                        Assert.AreEqual(WFCStatus.Success, explicitFlat.Solve(seed, default, weights, 100, windows));
                        CollectionAssert.AreEqual(implicitFlat.Layout, explicitFlat.Layout);
                    }

                    row++;
                }
            }
        }
    }
}
